Generators compose into memory-efficient pipelines:

```python
def read_lines(path):
    with open(path) as f:
        yield from f                       # 1. lazy I/O

def parse(lines):
    for line in lines:
        yield line.strip().split(",")      # 2. transform

def filter_valid(records):
    for r in records:
        if len(r) == 3: yield r            # 3. filter

def to_dict(records):
    for a, b, c in records:
        yield {"a": a, "b": b, "c": c}     # 4. shape

# Wire together — nothing runs until iterated
records = to_dict(filter_valid(parse(read_lines("data.csv"))))
for r in records: ...
```

Each stage processes one record at a time → constant memory, regardless of file size.

### Sliding window

```python
from collections import deque
def window(it, n):
    it = iter(it); buf = deque(islice(it, n), maxlen=n)
    if len(buf) == n: yield tuple(buf)
    for x in it:
        buf.append(x); yield tuple(buf)
```

### Chunking

```python
def chunked(it, n):
    it = iter(it)
    while chunk := list(islice(it, n)):
        yield chunk
```

### Unique preserving order

```python
def unique(it):
    seen = set()
    for x in it:
        if x not in seen:
            seen.add(x); yield x
```

